    [Header("Run speed scaling")]
    [Tooltip("Movement speed that maps to 1× animation speed.")]
    [SerializeField] private float _runSpeedBase = 5f;

    [Header("Facing (sprite flip)")]
    [Tooltip("SpriteRenderer to flip. Auto-found on _visualRoot at Awake if left empty.")]
    [SerializeField] private SpriteRenderer _sprite;
    [Tooltip("Min horizontal speed before facing updates.")]
    [SerializeField, Range(0f, 1f)] private float _faceDeadzone = 0.05f;

    [Header("Visual Center (for throw origin & aim reticle)")]
    [Tooltip("Half the sprite's visible height in world units. Used to compute the billboard's visual centre for camera-corrected spawn/reticle positions.")]
    [SerializeField, Range(0f, 3f)] private float _spriteHalfHeight = 0.5f;

    [Header("Normal Maps")]
    [Tooltip("Material whose _BumpMap will be swapped at runtime.")]
    [SerializeField] private Material _spriteMaterial;
    [Tooltip("Normal map for idle / non-run states.")]
    [SerializeField] private Texture _idleNormal;
    [Tooltip("Normal map for the run state.")]
    [SerializeField] private Texture _runNormal;

    // ── Cached references ──────────────────────────────────────────────────────

    private Animator _animator;

    // Held while idle so the blend tree doesn't snap back to Down on release.
    private int _lastFacingDir;
    private bool _lastFlipX;
    private string _lastStateName;

    // ── Animator parameter hashes ─────────────────────────────────────────────

    private static readonly int SpeedHash       = Animator.StringToHash("Speed");
    private static readonly int IsGroundedHash  = Animator.StringToHash("IsGrounded");
    private static readonly int JumpHash        = Animator.StringToHash("Jump");
    private static readonly int SwingHash       = Animator.StringToHash("Swing");
    private static readonly int HoldHash        = Animator.StringToHash("Hold");
    private static readonly int ThrowHash       = Animator.StringToHash("Throw");
    private static readonly int ScanHash        = Animator.StringToHash("Scan");
    private static readonly int FacingDirHash   = Animator.StringToHash("FacingDir");

    // ── IPlayerVisual ─────────────────────────────────────────────────────────

    public Vector3 VisualCenter =>
        _visualRoot != null
            ? _visualRoot.position + _visualRoot.up * _spriteHalfHeight
            : transform.position;

    public Vector3 VisualGroundCenter =>
        new Vector3(VisualCenter.x, transform.position.y, VisualCenter.z);

    public bool IsAttacking =>
        _animator != null &&
        (_animator.GetCurrentAnimatorStateInfo(0).IsName("Swing") ||
         (_animator.IsInTransition(0) &&
          _animator.GetNextAnimatorStateInfo(0).IsName("Swing")));

    public void TriggerAttack(int animIndex)
    {
        // Legacy tool-index attack stubbed — use TriggerSwing instead.
    }

    public void BeginChargePose(int animIndex)
    {
        // Legacy charge windup stubbed.
    }

    public void UpdateChargePose(int animIndex, float charge01)
    {
        // Legacy charge scrub stubbed.
    }

    public void ReleaseSwing(int animIndex, float animSpeed)
    {
        Debug.Log($"[Anim] Swing (animIndex={animIndex}, speed={animSpeed:F2}, facing={_lastFacingDir}, flip={_lastFlipX}, animator={(_animator != null ? "ok" : "NULL")})");
        if (_animator == null) return;
        _animator.SetTrigger(SwingHash);
    }

    public void CancelSwing()
    {
        Debug.Log($"[Anim] CancelSwing → Idle (animator={(_animator != null ? "ok" : "NULL")})");
        if (_animator == null) return;
        _animator.Play("Idle", 0, 0f);
    }

    /// <summary>No-op. Facing is now driven by camera-relative FacingDir + sprite flip in Update.</summary>
    public void FaceWorldDirection(Vector3 worldDir) { }

    // ── Frame-by-frame trigger API ────────────────────────────────────────────

    public void TriggerJump()
    {
        Debug.Log($"[Anim] Jump (animator={(_animator != null ? "ok" : "NULL")})");
        if (_animator == null) return;
        _animator.SetTrigger(JumpHash);
    }

    public void TriggerSwing()
    {
        Debug.Log($"[Anim] Swing (facing={_lastFacingDir}, flip={_lastFlipX}, animator={(_animator != null ? "ok" : "NULL")})");
        if (_animator == null) return;
        _animator.SetTrigger(SwingHash);
    }

    public void SetHolding(bool holding)
    {
        Debug.Log($"[Anim] Hold = {holding} (animator={(_animator != null ? "ok" : "NULL")})");
        if (_animator == null) return;
        _animator.SetBool(HoldHash, holding);
    }

    public void TriggerThrow()
    {
        Debug.Log($"[Anim] Throw (animator={(_animator != null ? "ok" : "NULL")})");
        if (_animator == null) return;
        _animator.SetTrigger(ThrowHash);
    }

    public void TriggerScan()
    {
        Debug.Log($"[Anim] Scan (animator={(_animator != null ? "ok" : "NULL")})");
        if (_animator == null) return;
        _animator.SetTrigger(ScanHash);
    }

    // ── Unity messages ────────────────────────────────────────────────────────

    private void Awake()
    {
        // Get Animator from the Visual child (not self)
        if (_visualRoot != null)
        {
            _animator = _visualRoot.GetComponent<Animator>();
            if (_sprite == null) _sprite = _visualRoot.GetComponentInChildren<SpriteRenderer>();
            _visualRoot.localScale = Vector3.one * _visualScale;
        }
        if (_camera == null) _camera = Camera.main;
        Debug.Log($"[Anim] Awake — visualRoot={(_visualRoot != null ? _visualRoot.name : "NULL")}, animator={(_animator != null ? "ok" : "NULL")}, sprite={(_sprite != null ? _sprite.name : "NULL")}");
    }

    private void Update()
    {
        if (_animator == null || _controller == null) return;

        Vector3 velocity = _controller.MoveInput;
        Vector2 xz = new Vector2(velocity.x, velocity.z);

        // Feed Speed and IsGrounded for locomotion
        _animator.SetFloat(SpeedHash, xz.magnitude);
        _animator.SetBool(IsGroundedHash, _controller.IsGrounded);

        // ── Camera-relative facing direction ──────────────────────────────────
        // Down = toward camera, Up = away from camera, Left = screen-left
        if (_camera != null && xz.sqrMagnitude >= _faceDeadzone * _faceDeadzone)
        {
            Vector3 camFwd   = Vector3.ProjectOnPlane(_camera.transform.forward, Vector3.up).normalized;
            Vector3 camRight = Vector3.ProjectOnPlane(_camera.transform.right, Vector3.up).normalized;

            float intoScreen  = Vector3.Dot(velocity, camFwd);    // + = away from camera = Up
            float screenRight = Vector3.Dot(velocity, camRight);  // + = screen-right

            // Angle from Down (toward camera), counterclockwise = screen-left
            float angle = Mathf.Atan2(-screenRight, -intoScreen) * Mathf.Rad2Deg;
            if (angle < 0f) angle += 360f;

            // Right-side facing → mirror angle to left side for sector calc
            bool flip = angle > 180f;
            if (flip) angle = 360f - angle;

            // 8 sectors: 0=Down, 1=DownLeft, 2=Left, 3=UpLeft, 4=Up, 5=UpRight, 6=Right, 7=DownRight
            int dir;
            if      (angle < 22.5f)  dir = 0; // Down
            else if (angle < 67.5f)  dir = 1; // DownLeft / DownRight
            else if (angle < 112.5f) dir = 2; // Left / Right
            else if (angle < 157.5f) dir = 3; // UpLeft / UpRight
            else                     dir = 4; // Up

            // Map right-side angles to their FacingDir values
            if (flip)
            {
                // Mirror: DownLeft→DownRight(7), Left→Right(6), UpLeft→UpRight(5), Up stays(4), Down stays(0)
                dir = dir switch
                {
                    1 => 7, // DownRight
                    2 => 6, // Right
                    3 => 5, // UpRight
                    _ => dir
                };
            }

            // All 8 directions now have dedicated sprites — no flip needed
            _animator.SetFloat(FacingDirHash, dir);
            if (_sprite != null) _sprite.flipX = false;

            _lastFacingDir = dir;
            _lastFlipX = false;
        }
        else
        {
            // Hold last facing when idle
            _animator.SetFloat(FacingDirHash, _lastFacingDir);
            if (_sprite != null) _sprite.flipX = _lastFlipX;
        }

        // ── Scale Run animation speed by actual horizontal velocity ────────────
        var stateInfo = _animator.GetCurrentAnimatorStateInfo(0);
        if (stateInfo.IsName("Run"))
        {
            var rb = _controller.GetComponent<Rigidbody>();
            float hSpeed = rb != null
                ? new Vector2(rb.velocity.x, rb.velocity.z).magnitude
                : xz.magnitude;
            _animator.speed = Mathf.Max(hSpeed / _runSpeedBase, 0.25f);
        }
        else
        {
            _animator.speed = 1f;
        }

        // ── Swap normal map based on current state ─────────────────────────────
        SwapNormalMap(stateInfo);
    }

    // ── Normal map swapping ───────────────────────────────────────────────────

    private void SwapNormalMap(AnimatorStateInfo stateInfo)
    {
        if (_spriteMaterial == null) return;

        string stateName = null;
        if (stateInfo.IsName("Run")) stateName = "Run";
        else if (stateInfo.IsName("Idle")) stateName = "Idle";

        if (stateName == _lastStateName) return;
        _lastStateName = stateName;

        var normal = stateName == "Run" ? _runNormal : _idleNormal;
        if (normal != null)
            _spriteMaterial.SetTexture("_BumpMap", normal);
    }
}

using UnityEngine;

/// <summary>
/// Attach to any GameObject that should be billboarded by the central
/// BillboardManager. Replaces the per-object Billboard.cs approach.
///
/// OnEnable finds the BillboardManager and registers; OnDisable unregisters.
/// Configure BillboardMode in the inspector to control rotation behaviour.
/// </summary>
[RequireComponent(typeof(Transform))]
public class BillboardRegistration : MonoBehaviour, IBillboardTarget
{
    [SerializeField] private BillboardMode _mode = BillboardMode.PitchOnly;

    public Transform BillboardTransform => transform;
    public BillboardMode Mode => _mode;

    private BillboardManager _manager;

    private void OnEnable()
    {
        if (_manager == null)
            _manager = FindObjectOfType<BillboardManager>();

        if (_manager != null)
            _manager.Register(this);
        else
            Debug.LogWarning("[BillboardRegistration] No BillboardManager found in scene.", this);
    }

    private void OnDisable()
    {
        if (_manager != null)
            _manager.Unregister(this);
    }
}

using UnityEngine;

public enum BillboardMode { Full, YOnly, PitchOnly, SpriteBillboard }

public interface IBillboardTarget
{
    Transform BillboardTransform { get; }
    BillboardMode Mode { get; }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// Central manager that drives billboard rotation for all registered
/// IBillboardTarget objects from a single LateUpdate loop.
///
/// Replace per-object Billboard.cs Update overhead with a single pass.
/// Existing Billboard.cs components continue working independently for
/// backward compatibility.
/// </summary>
[DefaultExecutionOrder(-100)]
public class BillboardManager : MonoBehaviour
{
    private readonly List<IBillboardTarget> _targets = new();
    private Camera _mainCamera;
    private bool _cameraCached;

    /// <summary>Register a target to receive automatic billboarding.</summary>
    public void Register(IBillboardTarget target)
    {
        if (target == null) return;
        if (!_targets.Contains(target))
            _targets.Add(target);
    }

    /// <summary>Unregister a target so it no longer receives billboarding.</summary>
    public void Unregister(IBillboardTarget target)
    {
        if (target == null) return;
        _targets.Remove(target);
    }

    private void CacheCamera()
    {
        if (!_cameraCached)
        {
            _mainCamera = Camera.main;
            _cameraCached = true;
        }
    }

    private void LateUpdate()
    {
        CacheCamera();
        if (_mainCamera == null) return;

        Vector3 cameraPos = _mainCamera.transform.position;

        for (int i = _targets.Count - 1; i >= 0; i--)
        {
            IBillboardTarget target = _targets[i];
            if (target?.BillboardTransform == null)
            {
                _targets.RemoveAt(i);
                continue;
            }

            Transform t = target.BillboardTransform;
            Vector3 dirToCamera = cameraPos - t.position;

            switch (target.Mode)
            {
                case BillboardMode.Full:
                    t.rotation = Quaternion.LookRotation(dirToCamera);
                    break;

                case BillboardMode.YOnly:
                    Vector3 flatDir = new Vector3(dirToCamera.x, 0f, dirToCamera.z);
                    if (flatDir.sqrMagnitude > 0.001f)
                        t.rotation = Quaternion.LookRotation(flatDir);
                    break;

                case BillboardMode.PitchOnly:
                    float horizontalDist = new Vector2(dirToCamera.x, dirToCamera.z).magnitude;
                    float pitchAngle = Mathf.Atan2(dirToCamera.y, horizontalDist) * Mathf.Rad2Deg;
                    t.rotation = Quaternion.Euler(pitchAngle, t.eulerAngles.y, 0f);
                    break;

                case BillboardMode.SpriteBillboard:
                    // Preserve the initial X tilt (e.g. 90° for upright sprites)
                    // and only rotate Y to face the camera on the horizontal plane.
                    Vector3 spriteFlatDir = new Vector3(dirToCamera.x, 0f, dirToCamera.z);
                    if (spriteFlatDir.sqrMagnitude > 0.001f)
                    {
                        float yAngle = Quaternion.LookRotation(spriteFlatDir).eulerAngles.y;
                        t.rotation = Quaternion.Euler(t.localEulerAngles.x, yAngle, 0f);
                    }
                    break;
            }
        }
    }
}

using UnityEngine;

/// <summary>
/// The visual/animation surface the player's combat &amp; interaction controllers drive,
/// decoupled from how the body is actually rendered. Implemented by both the legacy
/// sprite-sheet driver (<see cref="FlynnAnimationDriver"/>) and the procedural cube-rig
/// driver (<see cref="ProceduralCharacterDriver"/>) so the same wrench/throw/rope/reticle
/// logic works against either body without edits.
///
/// Controllers resolve it via <c>GetComponent&lt;IPlayerVisual&gt;()</c> in Awake.
/// </summary>
public interface IPlayerVisual
{
    /// <summary>World-space "hand" / chest origin for thrown projectiles and the rope end.</summary>
    Vector3 VisualCenter { get; }

    /// <summary>VisualCenter projected to the character's foot Y (ground-plane indicators).</summary>
    Vector3 VisualGroundCenter { get; }

    /// <summary>True while an attack/swing is playing (gates re-triggering).</summary>
    bool IsAttacking { get; }

    /// <summary>Fire the attack pose for the given tool index (1=pick 2=axe 3=hammer 4=wrench).</summary>
    void TriggerAttack(int animIndex);

    /// <summary>Enter the windup hold for the given tool index.</summary>
    void BeginChargePose(int animIndex);

    /// <summary>Scrub the windup pose with charge fraction 0→1 (also live-swaps the tool).</summary>
    void UpdateChargePose(int animIndex, float charge01);

    /// <summary>Release the swing at the given playback speed (higher = faster follow-through).</summary>
    void ReleaseSwing(int animIndex, float animSpeed);

    /// <summary>Abort a windup and return to neutral.</summary>
    void CancelSwing();

    /// <summary>Orient the body toward a world-space XZ direction. Ignores Y; no-op on zero.</summary>
    void FaceWorldDirection(Vector3 worldDir);
}

using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.Animations;
using UnityEngine;

/// <summary>
/// Editor utility that builds Flynn's AnimatorController for a 4-direction animation system
/// (Down, Up, Left, Right-via-flip). FacingDir values: 0=Down, 1=Up, 2=Left.
/// Run via menu: Flynn → Setup Animations
/// </summary>
public static class FlynnAnimationSetup
{
    private const string AnimOut = "Assets/Flynn/Animations";
    private const float  Fps     = 12f;
    private const string SpBase  = "Assets/Flynn/Sprites/character_animations";

    // ── Facing direction definitions ──────────────────────────────────────

    private static readonly (string name, int facingDir, string spriteFolder)[] Directions =
    {
        ("Down", 0, SpBase + "/positive"),
        ("Up",   1, SpBase + "/back"),
        ("Left", 2, SpBase + "/side"),
    };

    // dirName, spriteFolder, idle subfolder, run subfolder, jump subfolder
    // Up only has a run clip — idle/jump fall back to Down.
    private static readonly (string dir, string folder, string idleSub, string runSub, string jumpSub, bool hasIdle, bool hasJump)[] LocomotionDefs =
    {
        ("Down", "positive", "idel_02", "run_01", "jump_02", true,  true),
        ("Up",   "back",     null,      "run_01", null,      false, false),
        ("Left", "side",     "idel_03", "run_03", "jump_03", true,  true),
    };

    // ── Entry point ──────────────────────────────────────────────────────

    [MenuItem("Flynn/Setup Animations")]
    public static void Run()
    {
        if (!AssetDatabase.IsValidFolder(AnimOut))
            AssetDatabase.CreateFolder("Assets/Flynn", "Animations");

        var clips = BuildAllClips();
        BuildController(clips);

        AssetDatabase.SaveAssets();
        AssetDatabase.Refresh();
        Debug.Log("[FlynnAnimationSetup] All done — 4-direction controller built.");
    }

    // ── Clip creation ────────────────────────────────────────────────────

    private static Dictionary<string, AnimationClip> BuildAllClips()
    {
        var map = new Dictionary<string, AnimationClip>();

        // Locomotion: Idle, Run, Jump per direction (from sprite folders)
        foreach (var (dir, folder, idleSub, runSub, jumpSub, hasIdle, hasJump) in LocomotionDefs)
        {
            if (hasIdle) TryMakeClip(map, $"Flynn_Idle_{dir}", $"{SpBase}/{folder}/{idleSub}", true);
            TryMakeClip(map, $"Flynn_Run_{dir}",  $"{SpBase}/{folder}/{runSub}",  true);
            if (hasJump) TryMakeClip(map, $"Flynn_Jump_{dir}", $"{SpBase}/{folder}/{jumpSub}", false);
        }

        // Action clips: load existing (Flynn_Swing_Down, Flynn_Hold_Up, etc.)
        string[] actions = { "Swing", "Hold", "Throw", "Scan" };
        string[] dirs    = { "Down", "Up", "Left" };
        foreach (var action in actions)
        {
            foreach (var dir in dirs)
            {
                string clipName = $"Flynn_{action}_{dir}";
                string path = $"{AnimOut}/{clipName}.anim";
                var clip = AssetDatabase.LoadAssetAtPath<AnimationClip>(path);
                if (clip != null)
                {
                    map[clipName] = clip;
                    Debug.Log($"[FlynnAnimationSetup] Loaded existing '{clipName}'");
                }
                else
                {
                    Debug.LogWarning($"[FlynnAnimationSetup] Missing action clip: {clipName}");
                }
            }
        }

        return map;
    }

    private static void TryMakeClip(Dictionary<string, AnimationClip> map, string clipName, string folder, bool loop)
    {
        // Prefer loading existing clip (preserves GUID references)
        string outPath = $"{AnimOut}/{clipName}.anim";
        var existing = AssetDatabase.LoadAssetAtPath<AnimationClip>(outPath);
        if (existing != null)
        {
            map[clipName] = existing;
            Debug.Log($"[FlynnAnimationSetup] Loaded existing '{clipName}'");
            return;
        }

        var clip = MakeClip(clipName, folder, loop);
        if (clip != null) map[clipName] = clip;
    }

    private static AnimationClip MakeClip(string clipName, string folder, bool loop)
    {
        string dataPath = Application.dataPath.Replace('\\', '/');
        string sysDir   = dataPath + "/" + folder.Substring("Assets/".Length);

        if (!Directory.Exists(sysDir))
        {
            Debug.LogWarning($"[FlynnAnimationSetup] Folder not found: {sysDir}");
            return null;
        }

        var pngPaths = Directory.GetFiles(sysDir, "*.png")
                                .Select(p => p.Replace('\\', '/'))
                                .OrderBy(Path.GetFileName)
                                .ToArray();

        var sprites = new List<Sprite>(pngPaths.Length);
        foreach (var full in pngPaths)
        {
            string assetPath = "Assets/" + full.Substring(dataPath.Length + 1);
            var sprite = AssetDatabase.LoadAssetAtPath<Sprite>(assetPath);
            if (sprite != null)
                sprites.Add(sprite);
            else
                Debug.LogWarning($"[FlynnAnimationSetup] Sprite not found at: {assetPath}");
        }

        if (sprites.Count == 0)
        {
            Debug.LogWarning($"[FlynnAnimationSetup] No sprites loaded for clip '{clipName}'");
            return null;
        }

        var clip = new AnimationClip { frameRate = Fps };

        var binding = new EditorCurveBinding
        {
            type         = typeof(SpriteRenderer),
            path         = "",
            propertyName = "m_Sprite"
        };

        var keys = new ObjectReferenceKeyframe[sprites.Count];
        for (int i = 0; i < sprites.Count; i++)
            keys[i] = new ObjectReferenceKeyframe { time = i / Fps, value = sprites[i] };

        AnimationUtility.SetObjectReferenceCurve(clip, binding, keys);

        var settings = AnimationUtility.GetAnimationClipSettings(clip);
        settings.loopTime = loop;
        AnimationUtility.SetAnimationClipSettings(clip, settings);
        clip.wrapMode = loop ? WrapMode.Loop : WrapMode.Once;

        string outPath = $"{AnimOut}/{clipName}.anim";
        if (AssetDatabase.LoadAssetAtPath<AnimationClip>(outPath) != null)
            AssetDatabase.DeleteAsset(outPath);

        AssetDatabase.CreateAsset(clip, outPath);
        EditorUtility.SetDirty(clip);

        Debug.Log($"[FlynnAnimationSetup] Created '{clipName}'  ({sprites.Count} frames, loop={loop})");
        return clip;
    }

    // ── AnimatorController creation ──────────────────────────────────────

    private static void BuildController(Dictionary<string, AnimationClip> clips)
    {
        string ctrlPath = $"{AnimOut}/Flynn_AnimatorController.controller";
        if (AssetDatabase.LoadAssetAtPath<AnimatorController>(ctrlPath) != null)
            AssetDatabase.DeleteAsset(ctrlPath);

        var ctrl = AnimatorController.CreateAnimatorControllerAtPath(ctrlPath);
        ctrl.AddParameter("Speed",      AnimatorControllerParameterType.Float);
        ctrl.AddParameter("IsGrounded", AnimatorControllerParameterType.Bool);
        ctrl.AddParameter("FacingDir",  AnimatorControllerParameterType.Int);
        ctrl.AddParameter("Jump",       AnimatorControllerParameterType.Trigger);
        ctrl.AddParameter("Swing",      AnimatorControllerParameterType.Trigger);
        ctrl.AddParameter("Hold",        AnimatorControllerParameterType.Bool);
        ctrl.AddParameter("Throw",      AnimatorControllerParameterType.Trigger);
        ctrl.AddParameter("Scan",       AnimatorControllerParameterType.Trigger);

        var sm = ctrl.layers[0].stateMachine;

        // ── Create all states ─────────────────────────────────────────────

        // Per-direction locomotion (Up only has Run; idle/jump fall back to Down)
        var states = new Dictionary<string, AnimatorState>();
        string[] dirs = { "Down", "Up", "Left" };

        float xBase = 0f;
        foreach (var dir in dirs)
        {
            if (dir != "Up")
            {
                var idle = AddState(sm, clips, $"Idle_{dir}", $"Flynn_Idle_{dir}", new Vector3(xBase,       0, 0));
                var run  = AddState(sm, clips, $"Run_{dir}",  $"Flynn_Run_{dir}",  new Vector3(xBase + 300, 0, 0));
                var jump = AddState(sm, clips, $"Jump_{dir}", $"Flynn_Jump_{dir}", new Vector3(xBase + 600, 0, 0));
                states[$"Idle_{dir}"] = idle;
                states[$"Run_{dir}"]  = run;
                states[$"Jump_{dir}"] = jump;
            }
            else
            {
                // Up: only a Run state
                var run = AddState(sm, clips, "Run_Up", "Flynn_Run_Up", new Vector3(xBase + 300, 0, 0));
                states["Run_Up"] = run;
            }

            xBase += 900f;
        }

        sm.defaultState = states["Idle_Down"];

        // Action states per direction
        string[] actions = { "Swing", "Hold", "Throw", "Scan" };
        float yAction = -250f;

        foreach (var action in actions)
        {
            float xAction = 0f;
            foreach (var dir in dirs)
            {
                string stateName = $"{action}_{dir}";
                var actionState = AddState(sm, clips, stateName, $"Flynn_{action}_{dir}",
                                           new Vector3(xAction, yAction, 0));
                states[stateName] = actionState;
                xAction += 300f;
            }
            yAction -= 200f;
        }

        // ── Locomotion transitions within each direction ──────────────────
        // Down & Left have full idle/run/jump. Up has only Run; idle & jump fall back to Down.

        foreach (var dir in dirs)
        {
            int dirVal = dir == "Down" ? 0 : dir == "Up" ? 1 : 2;
            AnimatorState idle = dir == "Up" ? states["Idle_Down"] : states[$"Idle_{dir}"];
            AnimatorState run  = states[$"Run_{dir}"];
            AnimatorState jump = dir == "Up" ? states["Jump_Down"] : states[$"Jump_{dir}"];

            // Idle → Run
            var t = MkTrans(idle, run);
            t.AddCondition(AnimatorConditionMode.Greater, 0.1f, "Speed");
            t.AddCondition(AnimatorConditionMode.Equals, dirVal, "FacingDir");

            // Idle → Jump
            t = MkTrans(idle, jump);
            t.AddCondition(AnimatorConditionMode.IfNot, 0f, "IsGrounded");
            t.AddCondition(AnimatorConditionMode.Equals, dirVal, "FacingDir");

            // Run → Idle (Up falls back to Idle_Down)
            t = MkTrans(run, idle);
            t.AddCondition(AnimatorConditionMode.Less, 0.1f, "Speed");

            t = MkTrans(run, idle);
            t.AddCondition(AnimatorConditionMode.NotEqual, dirVal, "FacingDir");

            // Run → Jump (Up falls back to Jump_Down)
            t = MkTrans(run, jump);
            t.AddCondition(AnimatorConditionMode.IfNot, 0f, "IsGrounded");

            // Jump → Idle
            t = MkTrans(jump, idle);
            t.AddCondition(AnimatorConditionMode.If,    0f,   "IsGrounded");
            t.AddCondition(AnimatorConditionMode.Less,  0.1f, "Speed");
            t.AddCondition(AnimatorConditionMode.Equals, dirVal, "FacingDir");

            // Jump → Run
            t = MkTrans(jump, run);
            t.AddCondition(AnimatorConditionMode.If,      0f,   "IsGrounded");
            t.AddCondition(AnimatorConditionMode.Greater, 0.1f, "Speed");
            t.AddCondition(AnimatorConditionMode.Equals, dirVal, "FacingDir");
        }

        // ── Cross-direction transitions (idle ↔ idle, run ↔ run) ──────────
        // Up has no Idle state; Run_Up ↔ other runs, and Idle_Down handles Up idle.

        for (int i = 0; i < dirs.Length; i++)
        {
            for (int j = 0; j < dirs.Length; j++)
            {
                if (i == j) continue;
                int toDirVal = dirs[j] == "Down" ? 0 : dirs[j] == "Up" ? 1 : 2;

                // Idle_i → Idle_j (Up has no idle, skip)
                if (dirs[i] != "Up" && dirs[j] != "Up")
                {
                    var t = MkTrans(states[$"Idle_{dirs[i]}"], states[$"Idle_{dirs[j]}"]);
                    t.AddCondition(AnimatorConditionMode.Equals, toDirVal, "FacingDir");
                }

                // Run_i → Run_j
                var runFrom = states[$"Run_{dirs[i]}"];
                var runTo   = states[$"Run_{dirs[j]}"];
                var tRun = MkTrans(runFrom, runTo);
                tRun.AddCondition(AnimatorConditionMode.Equals, toDirVal, "FacingDir");
            }
        }

        // Special: facing Up while idle → stays on Idle_Down (handled by Run→Idle_Down
        // transitions already, plus cross-direction from Idle_Down/Idle_Left with FacingDir==1).

        // ── Action transitions (AnyState → action per direction) ──────────

        // Swing
        foreach (var dir in dirs)
        {
            int dirVal = dir == "Down" ? 0 : dir == "Up" ? 1 : 2;
            var actionState = states[$"Swing_{dir}"];
            actionState.tag = "Attack";

            var anyTrans = sm.AddAnyStateTransition(actionState);
            anyTrans.hasExitTime         = false;
            anyTrans.duration            = 0f;
            anyTrans.canTransitionToSelf = false;
            anyTrans.AddCondition(AnimatorConditionMode.If,     0f,     "Swing");
            anyTrans.AddCondition(AnimatorConditionMode.Equals, dirVal, "FacingDir");

            // Exit: Up falls back to Idle_Down
            var exitIdle = dir == "Up" ? states["Idle_Down"] : states[$"Idle_{dir}"];
            var exitTrans = actionState.AddTransition(exitIdle);
            exitTrans.hasExitTime = true;
            exitTrans.exitTime    = 0.85f;
            exitTrans.duration    = 0f;
        }

        // Throw
        foreach (var dir in dirs)
        {
            int dirVal = dir == "Down" ? 0 : dir == "Up" ? 1 : 2;
            var actionState = states[$"Throw_{dir}"];

            var anyTrans = sm.AddAnyStateTransition(actionState);
            anyTrans.hasExitTime         = false;
            anyTrans.duration            = 0f;
            anyTrans.canTransitionToSelf = false;
            anyTrans.AddCondition(AnimatorConditionMode.If,     0f,     "Throw");
            anyTrans.AddCondition(AnimatorConditionMode.Equals, dirVal, "FacingDir");

            var exitIdle = dir == "Up" ? states["Idle_Down"] : states[$"Idle_{dir}"];
            var exitTrans = actionState.AddTransition(exitIdle);
            exitTrans.hasExitTime = true;
            exitTrans.exitTime    = 0.85f;
            exitTrans.duration    = 0f;
        }

        // Scan
        foreach (var dir in dirs)
        {
            int dirVal = dir == "Down" ? 0 : dir == "Up" ? 1 : 2;
            var actionState = states[$"Scan_{dir}"];

            var anyTrans = sm.AddAnyStateTransition(actionState);
            anyTrans.hasExitTime         = false;
            anyTrans.duration            = 0f;
            anyTrans.canTransitionToSelf = false;
            anyTrans.AddCondition(AnimatorConditionMode.If,     0f,     "Scan");
            anyTrans.AddCondition(AnimatorConditionMode.Equals, dirVal, "FacingDir");

            var exitIdle = dir == "Up" ? states["Idle_Down"] : states[$"Idle_{dir}"];
            var exitTrans = actionState.AddTransition(exitIdle);
            exitTrans.hasExitTime = true;
            exitTrans.exitTime    = 0.85f;
            exitTrans.duration    = 0f;
        }

        // Hold (bool)
        foreach (var dir in dirs)
        {
            int dirVal = dir == "Down" ? 0 : dir == "Up" ? 1 : 2;
            var holdState = states[$"Hold_{dir}"];
            var idleState = dir == "Up" ? states["Idle_Down"] : states[$"Idle_{dir}"];
            var runState  = states[$"Run_{dir}"];

            // Idle → Hold
            var t = MkTrans(idleState, holdState);
            t.AddCondition(AnimatorConditionMode.If,     0f,     "Hold");
            t.AddCondition(AnimatorConditionMode.Equals, dirVal, "FacingDir");

            // Run → Hold
            t = MkTrans(runState, holdState);
            t.AddCondition(AnimatorConditionMode.If,     0f,     "Hold");
            t.AddCondition(AnimatorConditionMode.Equals, dirVal, "FacingDir");

            // Hold → Idle (Hold=false, not moving) — Up falls back to Idle_Down
            t = MkTrans(holdState, idleState);
            t.AddCondition(AnimatorConditionMode.IfNot, 0f,   "Hold");
            t.AddCondition(AnimatorConditionMode.Less, 0.1f, "Speed");

            // Hold → Run (Hold=false, moving)
            t = MkTrans(holdState, runState);
            t.AddCondition(AnimatorConditionMode.IfNot,  0f,   "Hold");
            t.AddCondition(AnimatorConditionMode.Greater, 0.1f, "Speed");
        }

        // Jump trigger (from AnyState for air jump cases)
        // Up has no Jump state — FacingDir==1 goes to Jump_Down
        foreach (var dir in dirs)
        {
            int dirVal = dir == "Down" ? 0 : dir == "Up" ? 1 : 2;
            var jumpState = dir == "Up" ? states["Jump_Down"] : states[$"Jump_{dir}"];

            var anyTrans = sm.AddAnyStateTransition(jumpState);
            anyTrans.hasExitTime         = false;
            anyTrans.duration            = 0f;
            anyTrans.canTransitionToSelf = false;
            anyTrans.AddCondition(AnimatorConditionMode.If,     0f,     "Jump");
            anyTrans.AddCondition(AnimatorConditionMode.Equals, dirVal, "FacingDir");
        }

        EditorUtility.SetDirty(ctrl);
        Debug.Log("[FlynnAnimationSetup] AnimatorController created with 4-direction support.");
    }

    // ── Helpers ──────────────────────────────────────────────────────────

    private static AnimatorState AddState(
        AnimatorStateMachine sm,
        Dictionary<string, AnimationClip> clips,
        string stateName,
        string clipName,
        Vector3 position)
    {
        var state = sm.AddState(stateName, position);
        if (clips.TryGetValue(clipName, out var clip))
            state.motion = clip;
        else
            Debug.LogWarning($"[FlynnAnimationSetup] Clip '{clipName}' not found for state '{stateName}'");
        return state;
    }

    private static AnimatorStateTransition MkTrans(AnimatorState from, AnimatorState to)
    {
        var t = from.AddTransition(to);
        t.hasExitTime = false;
        t.duration    = 0f;
        t.exitTime    = 0f;
        return t;
    }
}

