        _PixelateFactor ("Pixelate Factor", Range(1, 12)) = 4
        _ColorSteps ("Color Steps (0 = off)", Range(0, 32)) = 0
        _Cutoff ("Alpha Cutoff", Range(0, 1)) = 0.5
        _AmbientBoost ("Ambient Boost", Range(0, 2)) = 1.0
    }

